function FeatureCard({ card, t, locale }) {
  const icons = {
    calendar: IconFeatureCalendar,
    clock: IconFeatureClock,
    holiday: IconFeatureHoliday,
  };
  const Icon = icons[card.icon] || IconFeatureCalendar;

  return (
    <article className="flex h-full flex-col">
      <span className="flex h-12 w-12 items-center justify-center rounded-full bg-[#293B93] text-white">
        <Icon className="h-5 w-5" />
      </span>
      <h3 className="Text mt-4 font-bold text-[#000]">
        {t(`features.${card.key}.title`, card.titleFallback)}
      </h3>
      <p className="TextSmall mt-1 flex-1 font-normal leading-[1.5] text-[#666666]">
        {t(`features.${card.key}.description`, card.descriptionFallback)}
      </p>
      <Link
        href={localizedHref(locale, card.href)}
        className="TextSmall mt-5 inline-block font-semibold text-[#666666] transition hover:no-underline"
      >
        {t(`features.${card.key}.link`, card.linkFallback)} →
      </Link>
    </article>
  );
}

const FEATURE_CARDS = [
  {
    key: "calendar",
    icon: "calendar",
    href: "/markets/economic-calendar",
    titleFallback: "Economic Calendar",
    descriptionFallback:
      "Stay updated with our economic calendar. Keep track of upcoming economic events and their effects on market movements.",
    linkFallback: "View economic calendar",
  },
  {
    key: "tradingHours",
    icon: "clock",
    href: "/markets/market-holidays#trading-hours",
    titleFallback: "Forex & CFD Trading Hours",
    descriptionFallback:
      "View the latest trading hours for Forex, Metals, Commodities, and other financial instruments.",
    linkFallback: "View trading hours",
  },
  {
    key: "holidays",
    icon: "holiday",
    href: "/markets/market-holidays#holiday-hours",
    titleFallback: "Holiday Hours & Notices",
    descriptionFallback:
      "Market holidays may affect trading schedules and volatility. Stay up to date with holiday trading hours.",
    linkFallback: "View holiday hours",
  },
];

function TradingViewScreener({
  locale = "en",
  height = WIDGET_HEIGHT,
  market = "america",
  defaultScreen = "earnings_this_month",
  colorTheme = "light",
  showToolbar = true,
  isTransparent = false,
  enableScrolling = true,
}) {
  const src = useMemo(() => {
    const config = {
      width: "100%",
      height,
      defaultColumn: "overview",
      defaultScreen,
      market,
      showToolbar,
      colorTheme,
      isTransparent,
      enableScrolling,
    };

    const encoded = encodeURIComponent(JSON.stringify(config));
    return `https://www.tradingview-widget.com/embed-widget/screener/?locale=${encodeURIComponent(
      locale
    )}#${encoded}`;
  }, [
    locale,
    height,
    market,
    defaultScreen,
    colorTheme,
    showToolbar,
    isTransparent,
    enableScrolling,
  ]);

  return (
    <iframe
      title="TradingView Screener"
      src={src}
      className="block w-full"
      style={{ height }}
      allowTransparency
    />
  );
}

export default function MarketsEconomicCalendarSection({ locale = "en" }) {
  const t = usePathTranslation("marketsPage.economicCalendarSection");

  return (
    <section className="overflow-x-hidden py-14 md:py-16">
      <div className="container min-w-0 max-w-full">
        <div className="mx-auto max-w-6xl">
          <h2 className="HeadingH2 font-bold text-[#293B93]">
            {t("title", "Economic Calendar")}
          </h2>

          <div className="mt-6 overflow-hidden rounded-2xl border border-[#E1E7F6] bg-white shadow-sm">
            <TradingViewScreener locale={locale} height={WIDGET_HEIGHT} />
          </div>

          <div className="mt-10 md:mt-14">
            <div className="hidden gap-5 md:grid md:grid-cols-3 md:gap-6">
              {FEATURE_CARDS.map((card) => (
                <FeatureCard key={card.key} card={card} t={t} locale={locale} />
              ))}
            </div>

            <div className="md:hidden">
              <MobilePeekCarousel
                items={FEATURE_CARDS}
                showArrows
                className="w-full min-w-0"
                trackClassName="-mx-4 px-4 min-w-0"
                slideClassName="!h-auto"
                renderItem={(card) => (
                  <div className="w-full min-w-0">
                    <FeatureCard card={card} t={t} locale={locale} />
                  </div>
                )}
              />
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
